class Solution {
public:
    int maxDistance(int arr[], int n) {
        long long max1 = -2000000000LL, min1 = 2000000000LL;
        long long max2 = -2000000000LL, min2 = 2000000000LL;
        for (int i = 0; i < n; ++i) {
            long long val1 = (long long)arr[i] + i;
            long long val2 = (long long)arr[i] - i;
            if (val1 > max1) max1 = val1;
            if (val1 < min1) min1 = val1;
            if (val2 > max2) max2 = val2;
            if (val2 < min2) min2 = val2;
        }
        long long res = (max1 - min1 > max2 - min2) ? (max1 - min1) : (max2 - min2);
        return (int)res;
    }
};
